import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());
    private DataSource dataSource;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            dataSource = (DataSource) ctx.lookup("java:comp/env/jdbc/userdb");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize datasource", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userId = request.getParameter("id");
        String fields = request.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid id format");
            return;
        }

        // fields parameter allows selecting which columns to return
        // Default fields if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "username, email, created_at";
        }

        String query = "SELECT " + fields + " FROM user_profiles WHERE user_id = " + userId;

        logger.info("Executing profile query for user_id=" + userId);

        try (Connection conn = dataSource.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();

            ResultSetMetaData meta = rs.getMetaData();
            int columnCount = meta.getColumnCount();

            out.print("{");
            if (rs.next()) {
                for (int i = 1; i <= columnCount; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    String val = rs.getString(i);
                    if (val == null) {
                        out.print("null");
                    } else {
                        out.print("\"" + val.replace("\"", "\\\"") + "\"");
                    }
                }
            } else {
                response.sendError(HttpServletResponse.SC_NOT_FOUND, "User not found");
                return;
            }
            out.print("}");
            out.flush();

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // Update profile - uses PreparedStatement (safe)
        String userId = request.getParameter("id");
        String displayName = request.getParameter("display_name");
        String bio = request.getParameter("bio");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid id");
            return;
        }

        String updateSql = "UPDATE user_profiles SET display_name = ?, bio = ? WHERE user_id = ?";
        try (Connection conn = dataSource.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(updateSql)) {
            pstmt.setString(1, displayName);
            pstmt.setString(2, bio);
            pstmt.setInt(3, Integer.parseInt(userId));
            int rows = pstmt.executeUpdate();

            response.setContentType("application/json");
            response.getWriter().print("{\"updated\":" + rows + "}");
        } catch (SQLException e) {
            logger.severe("Update error: " + e.getMessage());
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Update failed");
        }
    }
}
